#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct AgentReplyFailure {
    /// The `id` of the request this answers.
    pub reply_to: String,
    /// The `type` of the request this answers. Null when the agent did not know it.
    pub request: Option<RequestType>,
    /// Why it failed.
    pub error: AgentError,
}

impl AgentReplyFailure {
    /// The keys this object takes.
    pub const FIELDS: &'static [&'static str] = &["type", "reply_to", "request", "ok", "error"];
}

/// The answer to a request, in any order. A success carries the request's data, and a failure its
/// reason.
#[derive(Debug, Clone, PartialEq)]
pub enum AgentReply {
    Success(AgentReplySuccess),
    Failure(AgentReplyFailure),
}

impl Serialize for AgentReply {
    fn serialize<S: serde::Serializer>(&self, serializer: S) -> Result<S::Ok, S::Error> {
        let (tag, value) = match self {
            Self::Success(inner) => (true, serde_json::to_value(inner).map_err(serde::ser::Error::custom)?),
            Self::Failure(inner) => (false, serde_json::to_value(inner).map_err(serde::ser::Error::custom)?),
        };

        crate::support::with_tag("ok", Value::Bool(tag), value).serialize(serializer)
    }
}

impl<'de> Deserialize<'de> for AgentReply {
    fn deserialize<D: serde::Deserializer<'de>>(deserializer: D) -> Result<Self, D::Error> {
        let value = Value::deserialize(deserializer)?;

        match value.get("ok") {
            Some(Value::Bool(true)) => serde_json::from_value(value).map(Self::Success),
            Some(Value::Bool(false)) => serde_json::from_value(value).map(Self::Failure),
            _ => return Err(serde::de::Error::custom("unknown ok")),
        }
        .map_err(serde::de::Error::custom)
    }
}

