#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct RestorePoint {
    /// Team 1's side in that round. On a launch, the plugin seats players by it through warmup, before
    /// the load.
    pub team1_side: PlayingSide,
    /// The rules that the map was played under. A restore plays on under these rules instead of the
    /// rules of its launch.
    pub rules: MatchRules,
    /// The backup file as the engine wrote it, up to `MAX_BACKUP_FILE_CHARS` characters. The
    /// file holds the money and equipment of every player, keyed by account, and only
    /// `mp_backup_restore_load_file` reads it.
    ///
    /// The file is text with tabs and line breaks, so a file at the length cap stays within the frame
    /// limits once JSON escapes it. Rejected when it holds a lone UTF-16 surrogate.
    pub file: String,
    /// The one-based round that the backup starts. The file numbers rounds from zero, one lower.
    pub round: i64,
    /// Team 1's score before that round.
    pub team1_score: i64,
    /// Team 2's score before that round.
    pub team2_score: i64,
}

impl RestorePoint {
    /// The keys this object takes.
    pub const FIELDS: &'static [&'static str] = &["team1_side", "rules", "file", "round", "team1_score", "team2_score"];
}

/// A slot's id and ports.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct ServerSlot {
    /// The slot's id, 1 to 32 letters, digits, `_` and `-`. It is unique on its node.
    pub id: String,
    /// The game port, UDP. Every `port` and `tv_port` on a node is different, free on the host, and
    /// not `EVENT_RELAY_PORT`, the port the agent listens on for plugins.
    /// [Host networking](/how-it-works/#host-networking) explains why.
    pub port: i64,
    /// The GOTV port, UDP, under the same rules as `port`.
    pub tv_port: i64,
}

impl ServerSlot {
    /// The keys this object takes.
    pub const FIELDS: &'static [&'static str] = &["id", "port", "tv_port"];
}

/// A game server's state as its plugin reports it.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct ServerState {
    /// The map the server is on, up to `MAP_NAME_MAX_CHARS` characters.
    pub map_name: String,
    /// The loaded match and its team state. Null on a server without a match or after a refused
    /// config.
    pub r#match: Option<GetServerStatusReplyMatch>,
    /// Everyone connected, up to `MAX_SERVER_PLAYERS`.
    pub players: Vec<GetServerStatusReplyPlayers>,
    /// Why the plugin could not read or use the match config it was launched with, up to
    /// `CONFIG_ERROR_MAX_CHARS` characters. Null when the server has no match config or the
    /// plugin accepted it.
    pub config_error: Option<String>,
    /// Whether players can join. When `true`, the server is logged on to Steam and has loaded the map
    /// that its launch asked for, the workshop map when it has one. It stays `true` once set.
    ///
    /// CS2 does not fall back to an anonymous logon when Steam refuses its token, so `true` also
    /// indicates that Steam accepted the GSLT and that its last use can be updated.
    pub ready: bool,
    /// The SteamID64 that Steam gave the server when it logged on with its GSLT. Each token keeps
    /// one SteamID across logons, so a controller can look the server up in Steam's server list by
    /// it. The plugin also adds the `allocation_id` without its dashes to `sv_tags`, which that list
    /// shows. Null until `ready`.
    pub server_steam_id: Option<String>,
}

impl ServerState {
    /// The keys this object takes.
    pub const FIELDS: &'static [&'static str] = &["map_name", "match", "players", "config_error", "ready", "server_steam_id"];
}

/// The `start_server` refusals the agent sends before reserving a slot.
/// Nothing started, so another node may take the launch.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub enum StartRefusal {
    #[serde(rename = "no_free_slot")]
    NoFreeSlot,
    #[serde(rename = "maintenance_running")]
    MaintenanceRunning,
    #[serde(rename = "cs2_not_installed")]
    Cs2NotInstalled,
    #[serde(rename = "cs2_outdated")]
    Cs2Outdated,
    #[serde(rename = "node_unavailable")]
    NodeUnavailable,
    #[serde(rename = "shutting_down")]
    ShuttingDown,
}

impl StartRefusal {
    /// Every value, in the contract's order.
    pub const ALL: &'static [Self] =
        &[Self::NoFreeSlot, Self::MaintenanceRunning, Self::Cs2NotInstalled, Self::Cs2Outdated, Self::NodeUnavailable, Self::ShuttingDown];
}

/// Reads a validated value as the named schema's type and writes it back.
#[doc(hidden)]
pub fn round_trip(name: &str, value: Value) -> Option<Result<Value, serde_json::Error>> {
    fn via<T: Serialize + for<'de> Deserialize<'de>>(value: Value) -> Result<Value, serde_json::Error> {
        serde_json::to_value(serde_json::from_value::<T>(value)?)
    }

    Some(match name {
        "PlayingSide" => via::<PlayingSide>(value),
        "MatchRules" => via::<MatchRules>(value),
        "RosterTeam" => via::<RosterTeam>(value),
        "Roster" => via::<Roster>(value),
        "ConfiguredSlot" => via::<ConfiguredSlot>(value),
        "DemoUploadHeader" => via::<DemoUploadHeader>(value),
        "AgentConfigSchema" => via::<crate::config::AgentConfig>(value),
        "DemoRemovedReason" => via::<DemoRemovedReason>(value),
        "AgentErrorCode" => via::<AgentErrorCode>(value),
        "AgentError" => via::<AgentError>(value),
        "StuckServer" => via::<StuckServer>(value),
        "AgentInfo" => via::<AgentInfo>(value),
        "HostInfo" => via::<HostInfo>(value),
        "ReportedSlot" => via::<ReportedSlot>(value),
        "ControllerAddress" => via::<ControllerAddress>(value),
        "ReportedDemoUpload" => via::<ReportedDemoUpload>(value),
        "NodeSettings" => via::<NodeSettings>(value),
        "SlotState" => via::<SlotState>(value),
        "GsltState" => via::<GsltState>(value),
        "SlotStatus" => via::<SlotStatus>(value),
        "Cs2UpdateMode" => via::<Cs2UpdateMode>(value),
        "Cs2UpdateOutcome" => via::<Cs2UpdateOutcome>(value),
        "Cs2Update" => via::<Cs2Update>(value),
        "ImageUpdateStep" => via::<ImageUpdateStep>(value),
        "Cs2ImageUpdateOutcome" => via::<Cs2ImageUpdateOutcome>(value),
        "Cs2ImageUpdate" => via::<Cs2ImageUpdate>(value),
        "Cs2State" => via::<Cs2State>(value),
        "NodeUnavailableCode" => via::<NodeUnavailableCode>(value),
        "MaintenanceOperation" => via::<MaintenanceOperation>(value),
        "NodeUnavailable" => via::<NodeUnavailable>(value),
        "DemoFile" => via::<DemoFile>(value),
        "ServerExitReason" => via::<ServerExitReason>(value),
        "ServerExit" => via::<ServerExit>(value),
        "EventBacklog" => via::<EventBacklog>(value),
        "AgentUpdateOutcome" => via::<AgentUpdateOutcome>(value),
        "AgentUpdate" => via::<AgentUpdate>(value),
        "LogSource" => via::<LogSource>(value),
        "AgentLogLevel" => via::<AgentLogLevel>(value),
        "LogLine" => via::<LogLine>(value),
        "LogSourceSummary" => via::<LogSourceSummary>(value),
        "MatchPhase" => via::<MatchPhase>(value),
        "StartServerReply" => via::<StartServerReply>(value),
        "StopServerReply" => via::<StopServerReply>(value),
        "Side" => via::<Side>(value),
        "GetServerStatusReply" => via::<GetServerStatusReply>(value),
        "UpdateCs2Reply" => via::<UpdateCs2Reply>(value),
        "DeleteDemoReply" => via::<DeleteDemoReply>(value),
        "ReserveSlotReply" => via::<ReserveSlotReply>(value),
        "UpdateAgentReply" => via::<UpdateAgentReply>(value),
        "UpdateCs2ImageReply" => via::<UpdateCs2ImageReply>(value),
        "ConsoleCommandReply" => via::<ConsoleCommandReply>(value),
        "RestoreRoundReply" => via::<RestoreRoundReply>(value),
        "StartMatchReply" => via::<StartMatchReply>(value),
        "RequestType" => via::<RequestType>(value),
        "ResourceUsage" => via::<ResourceUsage>(value),
        "ResourceTick" => via::<ResourceTick>(value),
        "AgentStopReason" => via::<AgentStopReason>(value),
        "AgentToControllerMessage" => via::<AgentToControllerMessage>(value),
        "PlayerPosition" => via::<PlayerPosition>(value),
        "ChatColor" => via::<ChatColor>(value),
        "ChatTag" => via::<ChatTag>(value),
        "CloseReason" => via::<CloseReason>(value),
        "HelloRefusedReason" => via::<HelloRefusedReason>(value),
        "SlotEdit" => via::<SlotEdit>(value),
        "DemoUploadEdit" => via::<DemoUploadEdit>(value),
        "NodeSettingsEdit" => via::<NodeSettingsEdit>(value),
        "GameMode" => via::<GameMode>(value),
        "SidesMode" => via::<SidesMode>(value),
        "ReadyMode" => via::<ReadyMode>(value),
        "LaunchRules" => via::<LaunchRules>(value),
        "RestoreFile" => via::<RestoreFile>(value),
        "MatchConfig" => via::<MatchConfig>(value),
        "ServerLaunchConfig" => via::<ServerLaunchConfig>(value),
        "ControllerToAgentMessage" => via::<ControllerToAgentMessage>(value),
        "DamageCause" => via::<DamageCause>(value),
        "DemoUpload" => via::<DemoUpload>(value),
        "EventFrame" => via::<EventFrame>(value),
        "EventBatch" => via::<EventBatch>(value),
        "EventBatchFrame" => via::<EventBatchFrame>(value),
        "EventBatchReceipt" => via::<EventBatchReceipt>(value),
        "EventBatchRejection" => via::<EventBatchRejection>(value),
        "FireEnd" => via::<FireEnd>(value),
        "WorldPos" => via::<WorldPos>(value),
        "GrenadeKind" => via::<GrenadeKind>(value),
        "InventoryItem" => via::<InventoryItem>(value),
        "LimitCloseReason" => via::<LimitCloseReason>(value),
        "MapEndReason" => via::<MapEndReason>(value),
        "ReadyTeam" => via::<ReadyTeam>(value),
        "Weapon" => via::<Weapon>(value),
        "PlayerInventory" => via::<PlayerInventory>(value),
        "WeaponShots" => via::<WeaponShots>(value),
        "PlayerShots" => via::<PlayerShots>(value),
        "RoundEndReason" => via::<RoundEndReason>(value),
        "PluginToControllerMessage" => via::<PluginToControllerMessage>(value),
        "RestorePoint" => via::<RestorePoint>(value),
        "ServerSlot" => via::<ServerSlot>(value),
        "ServerState" => via::<ServerState>(value),
        "StartRefusal" => via::<StartRefusal>(value),
        _ => return None,
    })
}
